mapper.select:
SELECT i.id, i.file_name, i.file_url, i.file_path, i.file_hash, i.file_size, i.mime_type, i.extension, i.width, i.height, i.uploader_id, i.usage_count, i.status, i.created_at, i.updated_at, i.deleted_at, i.created_by, i.updated_by FROM images i
i.deleted_at IS NULL
AND i.file_name LIKE CONCAT('%', #{fileName}, '%')
AND i.mime_type LIKE CONCAT('%', #{mimeType}, '%')
AND i.status = #{status}
ORDER BY i.created_at DESC LIMIT #{offset}, #{limit}

mapper.delete:
DELETE FROM images
WHERE id IN

    #{id}
